H.background();
const g = 9.8, v0 = Math.max(1, P.v0), h0 = Math.max(1, P.h0);
const tFlight = Math.sqrt(2 * h0 / g);
const range = v0 * tFlight;
const v = H.plot2d({ xMin: 0, xMax: Math.max(10, range * 1.15), yMin: 0, yMax: Math.max(6, h0 * 1.15) });
v.grid(); v.axes();
const xf = (tt) => v0 * tt;
const yf = (tt) => h0 - 0.5 * g * tt * tt;
const pts = [];
for (let i = 0; i <= 80; i++) { const tt = tFlight * i / 80; pts.push([xf(tt), yf(tt)]); }
v.path(pts, { color: H.colors.accent, width: 3 });
const tt = (t % (tFlight + 0.5));
const cx = Math.min(xf(tt), range), cy = Math.max(0, yf(tt));
const vx = v0, vy = -g * Math.min(tt, tFlight);
v.dot(cx, cy, { r: 6, fill: H.colors.warn });
v.arrow(cx, cy, cx + vx * 0.25, cy, { color: H.colors.good, width: 2 });
v.arrow(cx, cy, cx, cy + vy * 0.25, { color: H.colors.violet, width: 2 });
H.text("Horizontal launch:  x = v0 t,  y = h0 - (1/2) g t^2", 24, 30, { color: H.colors.ink, size: 16, weight: 700 });
H.text("v0 = " + v0.toFixed(1) + " m/s   h0 = " + h0.toFixed(1) + " m   range = " + range.toFixed(2) + " m   t = " + tt.toFixed(2) + " s", 24, 52, { color: H.colors.sub, size: 12 });
H.legend([{ label: "vx (constant)", color: H.colors.good }, { label: "vy (grows)", color: H.colors.violet }], H.W - 175, 28);
